css:
.loader { --accent: var(--loader-color); width: var(--loader-size); height: calc(var(--loader-size) * .55); display: flex; align-items: flex-start; justify-content: center; }
.loader span { width: calc(var(--loader-size) * .19); height: calc(var(--loader-size) * .19); border-radius: 50%; background: radial-gradient(circle at 32% 30%, color-mix(in srgb, #fff 55%, var(--accent)), var(--accent)); transform-origin: 50% -160%; }
.loader span:first-child { animation: cradle-left calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
.loader span:last-child { animation: cradle-right calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
@keyframes cradle-left { 0%, 50%, 100% { transform: rotate(0); } 25% { transform: rotate(-48deg); } }
@keyframes cradle-right { 0%, 50%, 100% { transform: rotate(0); } 75% { transform: rotate(48deg); } }
